      "executiveSummary": "Trong khi tổng vốn hóa ngành ngân hàng tăng gần 90% so với cuối năm 2020, Vietcombank lại ghi nhận mức giảm gần 3%. Đáng chú ý, diễn biến trái ngược này xuất hiện dù lợi nhuận của ngân hàng đã tăng gần gấp đôi. Diễn biến này tác động trực tiếp tới cơ cấu nguồn vốn và chiến lược số hóa của các nhà băng.",
